const body = $('Webhook').first().json.body;
const staticData = $getWorkflowStaticData('global');

if (!staticData.usage) {
  staticData.usage = {
    total_requests: 0,
    total_tokens: { input: 0, output: 0 },
    total_cost_usd: 0,
    by_model: {},
    by_user: {},
    history: []
  };
}

const usage = staticData.usage;
const model = body.model || 'unknown';
const userId = body.user_id || 'anonymous';
const inputTokens = body.input_tokens || 0;
const outputTokens = body.output_tokens || 0;
const costUsd = body.cost_usd || 0;

usage.total_requests++;
usage.total_tokens.input += inputTokens;
usage.total_tokens.output += outputTokens;
usage.total_cost_usd += costUsd;

if (!usage.by_model[model]) {
  usage.by_model[model] = { requests: 0, tokens: { input: 0, output: 0 }, cost_usd: 0 };
}
usage.by_model[model].requests++;
usage.by_model[model].tokens.input += inputTokens;
usage.by_model[model].tokens.output += outputTokens;
usage.by_model[model].cost_usd += costUsd;

if (!usage.by_user[userId]) {
  usage.by_user[userId] = { requests: 0, tokens: { input: 0, output: 0 }, cost_usd: 0 };
}
usage.by_user[userId].requests++;
usage.by_user[userId].tokens.input += inputTokens;
usage.by_user[userId].tokens.output += outputTokens;
usage.by_user[userId].cost_usd += costUsd;

usage.history.push({
  timestamp: new Date().toISOString(),
  model,
  user_id: userId,
  input_tokens: inputTokens,
  output_tokens: outputTokens,
  cost_usd: costUsd
});
if (usage.history.length > 1000) {
  usage.history = usage.history.slice(-1000);
}

return [{
  json: {
    success: true,
    data: {
      tracked: true,
      current_totals: {
        requests: usage.total_requests,
        tokens: usage.total_tokens,
        cost_usd: usage.total_cost_usd
      }
    },
    meta: { provider: 'usage-tracker', action: 'track' }
  }
}];

const body = $('Webhook').first().json.body;
const staticData = $getWorkflowStaticData('global');
const usage = staticData.usage || { total_requests: 0, total_tokens: { input: 0, output: 0 }, total_cost_usd: 0, by_model: {}, by_user: {} };

const userId = body.user_id;
const model = body.model;

let data = {
  total_requests: usage.total_requests,
  total_tokens: usage.total_tokens,
  total_cost_usd: usage.total_cost_usd,
  by_model: usage.by_model,
  by_user: usage.by_user
};

if (userId && usage.by_user[userId]) {
  data = { user_id: userId, ...usage.by_user[userId] };
}

if (model && usage.by_model[model]) {
  data = { model: model, ...usage.by_model[model] };
}

return [{
  json: {
    success: true,
    data: data,
    meta: { provider: 'usage-tracker', action: 'get_stats' }
  }
}];

const body = $('Webhook').first().json.body;
const staticData = $getWorkflowStaticData('global');
const usage = staticData.usage || { history: [] };

const limit = body.limit || 100;
const userId = body.user_id;
const model = body.model;

let history = usage.history || [];

if (userId) {
  history = history.filter(h => h.user_id === userId);
}

if (model) {
  history = history.filter(h => h.model === model);
}

history = history.slice(-limit);

return [{
  json: {
    success: true,
    data: { history: history, count: history.length },
    meta: { provider: 'usage-tracker', action: 'get_history' }
  }
}];

const staticData = $getWorkflowStaticData('global');

staticData.usage = {
  total_requests: 0,
  total_tokens: { input: 0, output: 0 },
  total_cost_usd: 0,
  by_model: {},
  by_user: {},
  history: []
};

return [{
  json: {
    success: true,
    data: { reset: true, message: 'All usage statistics have been reset' },
    meta: { provider: 'usage-tracker', action: 'reset' }
  }
}];
